  applicable = !in_scope.empty? || unusable.positive?
  impact 0.7
  impact 0.0 unless applicable
  only_if('no aws_emr_security_configuration in scope') { applicable }

  in_scope.each do |id, region|
    describe aws_emr_security_configuration(security_configuration_name: id, aws_region: region) do
      its('encryption_in_transit') { should eq true }
    end
